return ['domain'=>'zinn-backups','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'sw','project-id-version'=>'zinn-backups','pot-creation-date'=>'2026-10-08T09:17:23+00:00','po-revision-date'=>'2026-10-08T09:17:23+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Backups'=>'Zinn® Backups','https://zinndigital.com/wordpress-plugins/zinn-backups'=>'https://zinndigital.com/wordpress-plugins/zinn-backups','Backs up your WordPress files and database to your own storage — Dropbox, Google Drive, Cloudflare R2, Amazon S3 or any S3-compatible bucket — restores them in one go, and imports backups made by other backup and migration plugins.'=>'Huhifadhi nakala ya faili zako na hifadhidata ya WordPress kwenye hifadhi yako binafsi — Dropbox, Google Drive, Cloudflare R2, Amazon S3 au ndoo yoyote inayooana na S3 — huzirejesha mara moja, na kuagiza nakala zilizotengenezwa na programu-jalizi nyingine za kuhifadhi nakala na uhamiaji.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Backups'=>'Nakala rudufu','Get Pro: schedules, several storages, encryption'=>'Pata Pro: ratiba, hifadhi kadhaa, usimbaji fiche','Working…'=>'Inashughulikiwa…','Finished'=>'Imekamilika','Failed'=>'Imeshindikana','Cancelled'=>'Imeghairiwa','Cancel'=>'Ghairi','Restore'=>'Rejesha','Delete'=>'Futa','Delete this backup from your storage? This cannot be undone.'=>'Futa nakala rudufu hii kutoka kwenye hifadhi yako? Kitendo hiki hakiwezi kutenduliwa.','No backups yet. Press “Back up now” to make the first one.'=>'Bado hakuna nakala rudufu. Bonyeza "Hifadhi nakala sasa" ili kuunda ya kwanza.','Reading your storage…'=>'Inasoma hifadhi yako…','a complete backup, as opposed to an incremental oneFull backup'=>'Nakala kamili ya akiba','a backup holding only what changed since an earlier oneIncremental backup'=>'Nakala ya ziada','Encrypted'=>'Imesimbwa','From another site'=>'Kutoka kwa tovuti nyingine','Database'=>'Hifadhidata','Files'=>'Faili','Uploading %1$s: %2$s%%'=>'Inapakia %1$s: %2$s%%','Sign in to Dropbox in the window that opened, then paste the code Dropbox shows you:'=>'Ingia katika Dropbox kwenye dirisha lililofunguka, kisha bandika msimbo ambao Dropbox inakuonyesha:','Saved.'=>'Imehifadhiwa.','Remove this destination from the plugin? The backups stored in it are not deleted.'=>'Ondoa lengwa hili kwenye programu-jalizi? Nakala rudufu zilizohifadhiwa ndani yake hazitafutwa.','Reload the page to see the restored site.'=>'Pakia upya ukurasa ili kuona tovuti iliyorejeshwa.','Storage'=>'Hifadhi','Import & migrate'=>'Leta & hamisha','Settings'=>'Mipangilio','Sections'=>'Sehemu','Google Drive is connected.'=>'Google Drive imeunganishwa.','Google Drive could not be connected.'=>'Google Drive haikuweza kuunganishwa.','Details'=>'Maelezo','Back up now'=>'Hifadhi nakala sasa','Backups go to your own storage, not this server. <a href="%s">Connect your storage</a> first.'=>'Nakala rudufu huenda kwenye hifadhi yako mwenyewe, si seva hii. Kwanza <a href="%s">unganisha hifadhi yako</a>.','What to back up'=>'Vitu vya kucheleza','Files and database'=>'Faili na hifadhidata','Database only'=>'Hifadhidata pekee','Files only'=>'Faili pekee','Note (optional)'=>'Dokezo (hiari)','Each part is uploaded to your storage and removed from this server before the next one is made, so the backup never takes up room on your hosting.'=>'Kila sehemu hupakiwa kwenye hifadhi yako na kuondolewa kwenye seva hii kabla ya inayofuata kutengenezwa, kwa hivyo nakala rudufu haichukui nafasi kwenye upangishaji wako kamwe.','Your backups'=>'Nakala zako za akiba','Refresh'=>'Onyesha upya','Restore this backup'=>'Rejesha nakala hii rudufu','Passphrase'=>'Kishazi cha siri','I understand this replaces this site’s files and database with the backup’s. Files that are not in the backup are kept.'=>'Ninaelewa kuwa hii inachukua nafasi ya faili na hifadhidata ya tovuti hii na zile za nakala rudufu. Faili ambazo haziko kwenye nakala rudufu zitawekwa.','Recent activity'=>'Shughuli za hivi karibuni','Backup'=>'Nakala rudufu','Restore / import'=>'Rejesha / leta','Running'=>'Inaendeshwa','Your storage'=>'Nafasi yako ya kuhifadhi' . "\0" . 'Vituo vyako vya uhifadhi','No storage yet. Choose where your backups go below.'=>'Bado hakuna hifadhi. Chagua hapa chini mahali nakala zako rudufu zinapoenda.','Ready'=>'Tayari','Not connected'=>'Haijaunganishwa','Connect'=>'Unganisha','Test'=>'Jaribu','Edit'=>'Hariri','Remove'=>'Ondoa','Add storage'=>'Ongeza nafasi ya kuhifadhi','Backups go to one storage destination. To use a different one, edit or remove the one above.'=>'Nakala rudufu huenda kwenye lengwa moja la hifadhi. Ili kutumia tofauti, hariri au ondoa ile iliyo hapo juu.','Kind of storage'=>'Aina ya hifadhi','Name (for you)'=>'Jina (kwa ajili yako)','Provider'=>'Mtoa huduma','Cloudflare account id'=>'Kitambulisho cha akaunti ya Cloudflare','Endpoint address'=>'Anwani ya mwisho','Region'=>'Eneo','Bucket'=>'Baketi','Access key id'=>'Kitambulisho cha ufunguo wa kufikia','Secret access key'=>'Ufunguo wa siri wa ufikiaji','Leave empty to keep the saved key'=>'Acha wazi ili kuhifadhi ufunguo uliohifadhiwa','For Cloudflare R2: in the Cloudflare dashboard open R2, create a bucket, then “Manage R2 API tokens” → create a token with Object Read & Write for that bucket, and copy the access key id and secret here.'=>'Kwa Cloudflare R2: kwenye dashibodi ya Cloudflare fungua R2, tengeneza bakuli (bucket), kisha “Manage R2 API tokens” → tengeneza tokeni yenye ruhusa za Object Read & Write kwa ajili ya bakuli hilo, na unakili kitambulisho cha ufunguo wa ufikiaji (access key id) na siri hapa.','Dropbox app key'=>'Ufunguo wa programu ya Dropbox','Create an app at dropbox.com/developers/apps (Scoped access, App folder) with the files.content.read, files.content.write and files.metadata.read permissions, and copy its App key here. Save, then press Connect.'=>'Unda programu kwenye dropbox.com/developers/apps (Scoped access, App folder) ukitumia ruhusa za files.content.read, files.content.write na files.metadata.read, kisha unakili App key yake hapa. Hifadhi, kisha ubonyeze Connect.','OAuth client id'=>'Kitambulisho cha mteja wa OAuth','OAuth client secret'=>'Siri ya mteja wa OAuth','Leave empty to keep the saved secret'=>'Acha tupu ili kuweka siri iliyohifadhiwa','In Google Cloud Console, enable the Google Drive API, then create an OAuth client of type “Web application” with this address as an authorised redirect URI:'=>'Kwenye Google Cloud Console, wezesha Google Drive API, kisha uunde mteja wa OAuth wa aina ya "Web application" ukitumia anwani hii kama URI ya kuelekeza kwingine iliyoidhinishwa:','Save, then press Connect. The plugin only sees the files it creates.'=>'Hifadhi, kisha bonyeza Unganisha. Programu-jalizi huona tu faili inazounda.','Folder inside the storage (optional)'=>'Folda ndani ya hifadhi (si lazima)','Save storage'=>'Hifadhi nafasi','Import a backup from another plugin or host'=>'Ingiza nakala rudufu kutoka kwa programu-jalizi nyingine au seva pangishi','Bring a site in from a backup made by UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate, or any zip/tar archive of a WordPress site with its .sql dump. The content goes into wp-content and the database replaces this site’s; addresses are changed to this site’s automatically.'=>'Leta tovuti kutoka kwa nakala rudufu iliyotengenezwa na UpdraftPlus, All-in-One WP Migration (.wpress), Duplicator (zip), BackWPup, WPvivid, Jetpack VaultPress Backup, BlogVault, Zinn® Migrate, au kumbukumbu yoyote ya zip/tar ya tovuti ya WordPress iliyo na dampo lake la .sql. Maudhui huenda kwenye wp-content na hifadhidata inachukua nafasi ya ile ya tovuti hii; anwani hubadilishwa kuwa za tovuti hii kiotomatiki.','Upload from your computer'=>'Pakia kutoka kwenye kompyuta yako','Choose every file of the backup at once (UpdraftPlus makes several). Large files are sent in small pieces, so your host’s upload limit does not apply.'=>'Chagua kila faili ya nakala rudufu mara moja (UpdraftPlus huunda kadhaa). Faili kubwa hutumwa kwa vipande vidogo, kwa hivyo kikomo cha upakiaji cha seva pangishi yako hakitumiki.','Or from links (Google Drive, Dropbox or any download address)'=>'Au kutoka kwa viungo (Google Drive, Dropbox au anwani yoyote ya kupakua)','One link per line. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link; turn sharing off again afterwards.'=>'Kiungo kimoja kwa kila mstari. Kwa Google Drive na Dropbox, shiriki faili na "mtu yeyote aliye na kiungo" na ubandike kiungo hicho; zima kushiriki tena baadaye.','Or a file already on this server'=>'Au faili ambayo tayari iko kwenye seva hii','Upload archives by FTP or your host’s file manager into %s and reload this page.'=>'Pakia kumbukumbu kwa FTP au kidhibiti faili cha mwenyeji wako kwenye %s na upakie upya ukurasa huu.','Or a deploy code from another site'=>'Au msimbo wa kupeleka kutoka tovuti nyingine','If another site gave you a Zinn® Backups deploy code, paste it here to copy that backup onto this site without sharing its storage keys. A code works for a few hours; treat it like a password.'=>'Ikiwa tovuti nyingine ilikupa msimbo wa kusambaza wa Zinn® Backups, ubandike hapa ili kunakili nakala hiyo kwenye tovuti hii bila kushiriki funguo zake za hifadhi. Msimbo hufanya kazi kwa saa chache; uchukulie kama nenosiri.','Passphrase (only if that backup is encrypted)'=>'Nenosiri (ikiwa tu nakala hiyo imesimbwa)','Import'=>'Leta','I understand the import replaces this site’s content and database. After it, sign in with an account from the imported site.'=>'Ninaelewa kuwa uingizaji unachukua nafasi ya maudhui na hifadhidata ya tovuti hii. Baada ya hapo, ingia ukitumia akaunti kutoka kwa tovuti iliyoingizwa.','Moving to Zinn® hosting?'=>'Unahamia kwenye upangishaji wa Zinn®?','Zinn Digital® can move your site for you from your old host. If your old host gives you no FTP, SSH or control-panel access, install Zinn® Migrate on the old site; it makes one archive you can import here or hand to Zinn®.'=>'Zinn Digital® inaweza kuhamisha tovuti yako kutoka kwa mpangishi wako wa zamani. Iwapo mpangishi wako wa zamani hakupi ufikiaji wa FTP, SSH au paneli dhibiti, sakinisha Zinn® Migrate kwenye tovuti ya zamani; inaunda kumbukumbu moja unayoweza kuingiza hapa au kuikabidhi kwa Zinn®.','What goes into a backup'=>'Ni nini kinachojumuishwa kwenye nakala rudufu','Include WordPress’s own files (wp-admin, wp-includes). Usually not needed: WordPress can always be reinstalled.'=>'Jumuisha faili za WordPress zenyewe (wp-admin, wp-includes). Kwa kawaida haihitajiki: WordPress inaweza kusakinishwa upya wakati wowote.','Also leave out these folders or files (one per line, relative to the WordPress folder)'=>'Pia acha folda au faili hizi (moja kwa kila mstari, kulingana na folda ya WordPress)','Always left out: caches, update scratch space, and other backup plugins’ own archive folders:'=>'Hutengwa kila wakati: kache, nafasi ya muda ya kusasisha, na folda za kumbukumbu za programu-jalizi nyingine za nakala rudufu:','Size of each part (MB)'=>'Ukubwa wa kila sehemu (MB)','Save settings'=>'Hifadhi mipangilio','A backup part could not be opened for writing. Check that wp-content has free space.'=>'Sehemu ya nakala rudufu haikuweza kufunguliwa ili kuandikwa. Angalia ikiwa wp-content ina nafasi tupu.','A backup part could not be written. Check that wp-content has free space.'=>'Sehemu ya nakala rudufu haikuweza kuandikwa. Angalia ikiwa wp-content ina nafasi ya kutosha.','Connect a storage destination on the Storage tab first: backups are kept in your own storage, not on this server.'=>'Unganisha kwanza lengwa la hifadhi kwenye kichupo cha Storage: nakala rudufu huwekwa kwenye hifadhi yako mwenyewe, si kwenye seva hii.','Multisite networks are not supported yet.'=>'Mitandao ya tovuti nyingi haitumiki kwa sasa.','This server’s PHP has no ZipArchive extension. Ask your host to enable it.'=>'PHP ya seva hii haina kiendelezi cha ZipArchive. Omba seva pangishi yako ikiwezeshe.','Starting'=>'Inaanza','Listing files'=>'Inaorodhesha faili','Backing up the database'=>'Inacheleza hifadhidata','Packing files'=>'Inafunga faili','Uploading to your storage'=>'Inapakia kwenye hifadhi yako','Finishing'=>'Inamaliza','The backup reached an unknown stage.'=>'Hifadhi rudufu ilifikia hatua isiyojulikana.','Backup %s started.'=>'Nakala rudufu ya %s imeanza.','Found %1$s files (%2$s).'=>'Mafaili %1$s yamepatikana (%2$s).','Database: %1$d tables, %2$s rows, %3$s compressed.'=>'Hifadhidata: majedwali %1$d, safu mlalo %2$s, %3$s imebanwa.','Backup complete: %1$s stored in %2$d destination.'=>'Nakala rudufu imekamilika: %1$s imehifadhiwa katika eneo %2$d.' . "\0" . 'Nakala rudufu imekamilika: %1$s imehifadhiwa katika maeneo %2$d.','Some parts already uploaded could not be removed from your storage; they are in an incomplete backup folder and are never offered for restore.'=>'Baadhi ya sehemu zilizokwisha kupakiwa hazikuweza kuondolewa kwenye hifadhi yako; ziko kwenye folda ya nakala rudufu isiyo kamili na kamwe hazitolewi kwa ajili ya kurejesha.','A storage destination was removed while the backup was running.'=>'Eneo la hifadhi liliondolewa wakati nakala rudufu ilipokuwa ikiendeshwa.','That is not a backup folder.'=>'Hiyo si folda ya nakala rudufu.','That storage destination is no longer saved on this site.'=>'Eneo hilo la kuhifadhia halijahifadhiwa tena kwenye tovuti hii.','Later incremental backups are built on this one. Delete those first.'=>'Nakala za ziada za baadaye zimejengwa juu ya hii. Futa hizo kwanza.','This file is not an encrypted Zinn® Backups file.'=>'Faili hili si faili lililosimbwa kwa njia fiche la Zinn® Backups.','The backup could not be decrypted: the passphrase is wrong or the file is damaged.'=>'Nakala rudufu haikuweza kufutwa usimbaji: neno la siri si sahihi au faili limeharibika.','The encrypted backup file is incomplete.'=>'Faili ya nakala rudufu iliyosimbwa haijakamilika.','The database file could not be written. Check that wp-content has free space.'=>'Faili la hifadhidata halikuweza kuandikwa. Angalia ikiwa wp-content ina nafasi tupu.','That is not a deploy code. A deploy code starts with zbdeploy1.'=>'Hiyo siyo msimbo wa kupeleka. Msimbo wa kupeleka huanza na zbdeploy1.','That deploy code is damaged. Copy it again from the other site.'=>'Nambari hiyo ya utumaji imeharibika. Inakili tena kutoka kwa tovuti nyingine.','The deploy code has expired or its backup was deleted. Make a new code on the other site.'=>'Nambari ya kuthibitisha kupeleka muda wake umekwisha au nakala yake imefutwa. Tengeneza nambari mpya kwenye tovuti nyingine.','That deploy code does not point at a Zinn® Backups backup.'=>'Msimbo huo wa upelekaji hauelekezi kwenye nakala rudufu ya Zinn® Backups.','The deploy code has expired. Make a new code on the other site.'=>'Nambari ya utumaji imeisha muda wake. Tengeneza nambari mpya kwenye tovuti nyingine.','The server stopped honouring partial downloads. Start the import again.'=>'Seva imeacha kukubali upakuaji wa sehemu. Anzisha uagizaji tena.','The link opened a web page instead of a file. For Google Drive and Dropbox, share the file with “anyone with the link” and paste that link.'=>'Kiungo kilifungua ukurasa wa wavuti badala ya faili. Kwa Google Drive na Dropbox, shiriki faili na "mtu yeyote aliye na kiungo" kisha ubandike kiungo hicho.','The link answered with HTTP %d.'=>'Kiungo kilijibu kwa HTTP %d.','The file list could not be written.'=>'Orodha ya faili haikuweza kuandikwa.','The storage service could not be reached: %s'=>'Huduma ya hifadhi haikuweza kufikiwa: %s','%1$s answered with HTTP %2$d: %3$s'=>'%1$s ilijibu kwa HTTP %2$d: %3$s','no details given'=>'Hakuna maelezo yaliyotolewa','You are not allowed to manage backups.'=>'Huruhusiwi kudhibiti nakala rudufu.','Tick the box to confirm that the restore replaces this site’s files and database.'=>'Weka alama kwenye kisanduku ili kuthibitisha kwamba urejeshaji unachukua nafasi ya faili na hifadhidata ya tovuti hii.','Save the destination first.'=>'Hifadhi lengwa kwanza.','Connected: a test file was written and removed.'=>'Imeunganishwa: faili ya jaribio imeandikwa na kuondolewa.','Enter the app key of your Dropbox app first (see the steps beside the form).'=>'Weka kwanza ufunguo wa programu wa programu yako ya Dropbox (tazama hatua zilizo kando ya fomu).','This kind of storage does not sign in.'=>'Aina hii ya hifadhi haiingii.','The sign-in expired. Press Connect again.'=>'Muda wa kuingia umeisha. Bonyeza Unganisha tena.','Dropbox is connected.'=>'Dropbox imeunganishwa.','Settings saved.'=>'Mipangilio imehifadhiwa.','Another backup, restore or import is running. Wait for it to finish, or cancel it.'=>'Nakala nyingine rudufu, urejeshaji au uingizaji unaendelea. Subiri ikamilike, au uighairi.','The upload was not started properly. Start again.'=>'Upakiaji haukuanza ipasavyo. Anza tena.','The chunk did not arrive. Your server may limit upload sizes; try again.'=>'Kipande hakijafika. Seva yako inaweza kuwa imeweka kikomo cha ukubwa wa kupakia; jaribu tena.','Tick the box to confirm that the import replaces this site’s content and database.'=>'Weka alama kwenye kisanduku ili kuthibitisha kwamba uingizaji unachukua nafasi ya maudhui na hifadhidata ya tovuti hii.','Choose an archive to import: upload it, paste a link, or pick one from the import folder.'=>'Chagua kumbukumbu ya kuingiza: ipakie, bandika kiungo, au chagua moja kutoka kwenye folda ya kuingiza.','Hosting customer? Get %1$d%% off %2$s'=>'Mteja wa upangishaji? Pata punguzo la %1$d%% kwa %2$s','As a Zinn Digital® hosting customer you get a personal code for %d%% off your first payment. Renewals are at the normal price.'=>'Kama mteja wa upangishaji wa Zinn Digital® unapata msimbo wa kibinafsi wa punguzo la %d%% kwenye malipo yako ya kwanza. Upyaji ni kwa bei ya kawaida.','Get my %d%% code and go to checkout'=>'Pata msimbo wangu wa %d%% na uende kulipa','Sorry, you are not allowed to do that.'=>'Samahani, hauruhusiwi kufanya hivyo.','This discount is for customers with a paid hosting plan in good standing. Free trials do not qualify.'=>'Punguzo hili ni kwa wateja walio na mpango wa huduma ya kulipia wa kupangisha wavuti usio na malimbikizo. Majaribio ya bure hayajumuishwi.','You have already used your hosting-customer discount for this plugin.'=>'Tayari umetumia punguzo lako la mteja wa upangishaji kwa programu-jalizi hii.','We could not get your code just now. Please try again in a few minutes.'=>'Hatujaweza kupata nambari yako ya kuthibitisha sasa hivi. Tafadhali jaribu tena baada ya dakika chache.','Reading the backup'=>'Inasoma nakala rudufu','Downloading the archive'=>'Inapakua kumbukumbu','Recognising the archive'=>'Inatambua kumbukumbu','Restoring files'=>'Inarejesha faili','Downloading the database'=>'Inapakua hifadhidata','Restoring the database'=>'Inarejesha hifadhidata','Updating the site address'=>'Inasasisha anwani ya tovuti','Switching to the restored database'=>'Inabadilisha hadi hifadhidata iliyorejeshwa','The restore reached an unknown stage.'=>'Urejeshaji umefikia hatua isiyojulikana.','This folder has no complete Zinn® Backups backup in it (the manifest is missing).'=>'Folda hii haina nakala rudufu kamili ya Zinn® Backups ndani yake (manifest haipo).','This backup is encrypted. Enter its passphrase to restore it.'=>'Nakala hii ya akiba imesimbwa kwa njia fiche. Weka kaulimbiu yake ili kuirejesha.','This incremental backup needs backup %s, which is no longer in the storage.'=>'Nakala hii ya ziada inahitaji nakala ya %s, ambayo haipo tena kwenye hifadhi.','Restoring the backup of %1$s (%2$d file parts).'=>'Inarejesha nakala rudufu ya %1$s (sehemu %2$d za faili).','%1$s file could not be overwritten because this site is not allowed to change it, and was left as it is: %2$s'=>'Faili la %1$s halikuweza kuandikwa upya kwa sababu tovuti hii hairuhusiwi kulibadilisha, na liliachwa kama lilivyo: %2$s' . "\0" . 'Faili %1$s hazikuweza kuandikwa upya kwa sababu tovuti hii hairuhusiwi kuzibadilisha, na ziliachwa kama zilivyo: %2$s','Restored %s files.'=>'Faili %s zimerejeshwa.','%s did not match its checksum after downloading. The copy in storage may be damaged.'=>'%s haikulingana na hundi yake baada ya kupakuliwa. Nakala iliyoko kwenye hifadhi inaweza kuwa imeharibika.','%s did not arrive. Upload it again.'=>'%s haikufika. Pakia tena.','Recognised: %s.'=>'Imetambuliwa: %s.','Imported %1$s files into wp-content (%2$s left out: caches, drop-ins and other backup plugins’ folders).'=>'Faili %1$s zimeingizwa kwenye wp-content (%2$s zimeachwa: akiba, drop-ins na folda za programu-jalizi nyingine za chelezo).','The archive has no database dump, so only files were imported.'=>'Kumbukumbu haina nakala ya hifadhidata, kwa hivyo faili pekee ndizo zilizoingizwa.','Database restored into %d temporary tables.'=>'Hifadhidata imerejeshwa katika majedwali ya muda %d.','%s has no WordPress tables in it and was skipped.'=>'%s haina majedwali ya WordPress ndani yake na ilirukwa.','The backup’s database has no WordPress tables, so nothing was replaced.'=>'Hifadhidata ya nakala rudufu haina majedwali ya WordPress, kwa hivyo hakuna kilichobadilishwa.','This backup is of a multisite network. Restoring a network into a single site is not supported.'=>'Nakala hii ya akiba ni ya mtandao wa tovuti nyingi (multisite). Kurejesha mtandao kwenye tovuti moja hakutumiki.','Moving the content from %1$s to %2$s.'=>'Inahamisha maudhui kutoka %1$s hadi %2$s.','Restore complete. If you are signed out, sign in with an account from the restored site.'=>'Urejeshaji umekamilika. Ikiwa umeondolewa, ingia ukitumia akaunti kutoka kwa tovuti iliyorejeshwa.','Restore complete.'=>'Urejeshaji umekamilika.','%1$s — trying again in %2$d seconds.'=>'%1$s — inajaribu tena baada ya sekunde %2$d.','Cancelled.'=>'Imeghairiwa.','Backups go to one storage destination. Edit or remove the one you have to use a different one.'=>'Nakala rudufu huenda kwenye lengwa moja la hifadhi. Hariri au ondoa uliyo nayo ili kutumia tofauti.','The database file could not be opened.'=>'Faili ya hifadhidata haikuweza kufunguliwa.','The database refused a statement from the backup: %1$s (%2$s…)'=>'Hifadhidata imekataa taarifa kutoka kwenye nakala rudufu: %1$s (%2$s…)','The restored tables could not be swapped in: %s. Your site is unchanged.'=>'Jedwali zilizorejeshwa hazikuweza kubadilishwa: %s. Tovuti yako haijabadilika.','There is no writable folder for temporary backup files. Make wp-content writable and try again.'=>'Hakuna folda inayoweza kuandikwa kwa ajili ya faili za muda za nakala rudufu. Fanya wp-content iweze kuandikwa na ujaribu tena.','Could not create a folder for this job.'=>'Haikuweza kuunda folda ya kazi hii.','%s — guides and services'=>'%s — miongozo na huduma','User guides'=>'Miongozo ya mtumiaji','Read the %s user guide'=>'Soma mwongozo wa mtumiaji wa %s','Hide this'=>'Ficha hii','Zinn® hosting for WordPress'=>'Ukarimu wa Zinn® kwa WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, nakala rudufu za kila siku, uhamishaji wa bila malipo na paneli dhibiti iliyoundwa kwa ajili ya watu wanaoendesha zaidi ya tovuti moja.','The Zinn® marketplace'=>'Soko la Zinn®','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Nunua na uuze tovuti zilizothibitishwa, vikoa na upangaji wa viungo, huku pesa zikiwa zimewekwa salama hadi pande zote mbili ziridhike.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — ajiri watu wanaofanya kazi hii kama taaluma yao','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Soko letu la kimataifa la wafanyakazi huru: vinjari zaidi ya huduma 10,000 zilizotengenezwa tayari kutoka kwa waandishi, wabunifu, watengenezaji programu na wataalamu wa SEO, au chapisha mradi na uwape nafasi ya kutoa zabuni.','See the Zinn Digital® release notes.'=>'Tazama madokezo ya toleo la Zinn Digital®.','The Zinn® update service did not issue a download link for this update. Check that this site can reach the Zinn® platform, then try again.'=>'Huduma ya usasishaji ya Zinn® haikutoa kiungo cha kupakua kwa usasishaji huu. Hakikisha tovuti hii inaweza kufikia jukwaa la Zinn®, kisha ujaribu tena.','The update could not be downloaded from the Zinn® update service (%s). Try again in a few minutes.'=>'Sasisho halikuweza kupakuliwa kutoka kwa huduma ya sasisho ya Zinn® (%s). Jaribu tena baada ya dakika chache.','The downloaded update failed its integrity check and was not installed.'=>'Sasisho lililopakuliwa limeshindwa ukaguzi wa uadilifu na halijasakinishwa.','The zip archive could not be opened. It may be damaged or incomplete.'=>'Hifadhi ya zip haikuweza kufunguliwa. Huenda imeharibika au haijakamilika.','This .wpress file uses a format we cannot read (it may be compressed or encrypted by All-in-One WP Migration). Export it again without encryption.'=>'Faili hii ya .wpress inatumia umbizo ambalo hatuwezi kusoma (huenda imebanwa au kusimbwa kwa njia fiche na All-in-One WP Migration). Isafirishe tena bila usimbaji fiche.','This is a Duplicator “DupArchive” (.daf) file. In Duplicator, build the package again with the archive format set to ZIP, then import that.'=>'Hili ni jalada la Duplicator “DupArchive” (.daf). Katika Duplicator, jenga kifurushi tena ukiweka muundo wa kumbukumbu kuwa ZIP, kisha uingize hiyo.','This UpdraftPlus database backup is encrypted. Decrypt it in UpdraftPlus (or turn off database encryption and back up again), then import it.'=>'Nakala hii rudufu ya hifadhidata ya UpdraftPlus imesimbwa kwa njia fiche. Ifungue katika UpdraftPlus (au zima usimbaji fiche wa hifadhidata kisha uhifadhi nakala tena), kisha uiingize.','Database dump'=>'Dampo ya hifadhidata','%s is not a backup archive we can read (zip, tar, tar.gz, .wpress, .sql or .sql.gz).'=>'%s si jalada la nakala rudufu ambalo tunaweza kusoma (zip, tar, tar.gz, .wpress, .sql au .sql.gz).','Website archive'=>'Kumbukumbu ya tovuti','%s has no WordPress content (no wp-content folder and no database dump) in it.'=>'%s haina maudhui yoyote ya WordPress (hakuna folda ya wp-content na hakuna dampo la hifadhidata) ndani yake.','This .wpress file is encrypted or compressed by All-in-One WP Migration. Export it again with encryption and compression switched off, then import that.'=>'Faili hili la .wpress limesimbwa au kubanwa na All-in-One WP Migration. Lihamishe tena huku usimbaji fiche na mgandamizo ukiwa umezimwa, kisha liingize.','Other S3-compatible storage'=>'Hifadhi nyingine inayooana na S3','Cloudflare R2, Amazon S3 or S3-compatible'=>'Cloudflare R2, Amazon S3 au patanifu na S3','The storage keys could not be read on this site. Enter the secret key again on the Storage tab.'=>'Vifunguo vya uhifadhi havikuweza kusomwa kwenye tovuti hii. Weka ufunguo wa siri tena kwenye kichupo cha Uhifadhi.','This kind of storage is not known.'=>'Aina hii ya uhifadhi haijulikani.','Choose a kind of storage.'=>'Chagua aina ya hifadhi.','Enter the bucket name and the access key.'=>'Weka jina la ndoo na ufunguo wa kufikia.','Enter your Cloudflare account id (or the full R2 endpoint).'=>'Weka kitambulisho cha akaunti yako ya Cloudflare (au mwisho kamili wa R2).','Enter the endpoint address of your storage.'=>'Weka anwani ya mwisho ya hifadhi yako.','Enter the OAuth client id from your Google Cloud project.'=>'Weka OAuth client id kutoka kwa mradi wako wa Google Cloud.','Dropbox did not return a refresh token. Start the connection again.'=>'Dropbox haikurudisha tokeni ya kuonyesha upya. Anzisha muunganisho tena.','Dropbox is not connected. Connect it again on the Storage tab.'=>'Dropbox haijaunganishwa. Iunganishe tena kwenye kichupo cha Hifadhi.','Google did not return a refresh token. Remove this site from your Google account’s third-party access and connect again.'=>'Google haikurudisha tokeni ya kuonyesha upya. Ondoa tovuti hii kwenye ufikiaji wa wahusika wengine katika akaunti yako ya Google kisha uunganishe tena.','That file is not in Google Drive any more.'=>'Faili hilo haliko tena kwenye Google Drive.','Google Drive is not connected. Connect it again on the Storage tab.'=>'Google Drive haijaunganishwa. Iunganishe tena kwenye kichupo cha Hifadhi.','The storage service did not start the upload.'=>'Huduma ya hifadhi haikuanza upakiaji.','The storage service sent a reply that could not be read.'=>'Huduma ya hifadhi imetuma jibu ambalo halikuweza kusomeka.','A temporary backup file could not be read.'=>'Faili la muda la chelezo halikuweza kusomwa.','A deploy link is read-only.'=>'Kiungo cha upelekaji ni cha kusoma tu.','The deploy code has no link for a file this backup needs.'=>'Msimbo wa usambazaji hauna kiungo cha faili ambayo nakala rudufu hii inahitaji.','The deploy link'=>'Kiungo cha kupeleka']];